:root {
  --bg: #fbfaf6; --surface: #ffffff; --raised: #f4f2ec; --line: #e6e2d8; --line-soft: #eeebe3;
  --text: #15181c; --soft: #4b525a; --muted: #8b9199;
  --accent: #43611b; --accent-bright: #5a7d27; --accent-ink: #ffffff; --accent-soft: #eaf1dc;
  --bad: #b4322f; --bad-soft: #fbe9e7; --warn: #8a5a00; --warn-soft: #fbf0d6; --info: #2f5bb5;
  --mono: "JetBrains Mono", ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --display: "Instrument Sans", "Space Grotesk", Inter, -apple-system, sans-serif;
  --radius: 18px;
  --shadow: 0 1px 2px rgba(20, 24, 28, .04), 0 12px 32px -12px rgba(20, 24, 28, .12);
}
* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body { margin: 0; background: var(--bg); color: var(--text); font: 16px/1.6 Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif; -webkit-font-smoothing: antialiased; }
a { color: inherit; text-decoration: none; }
h1, h2, h3, h4, p { margin: 0; }
h1, h2, h3 { font-family: var(--display); font-weight: 500; letter-spacing: -.025em; }
button, input, select { font: inherit; color: inherit; }
code, pre, .mono { font-family: var(--mono); font-size: 13px; }

/* floating pill navigation */
.pill { position: fixed; top: 22px; left: 50%; transform: translateX(-50%); z-index: 30; display: flex; align-items: center; gap: 6px; padding: 7px 7px 7px 18px; border-radius: 999px; background: rgba(255, 255, 255, .78); backdrop-filter: blur(16px) saturate(1.4); -webkit-backdrop-filter: blur(16px) saturate(1.4); border: 1px solid rgba(255, 255, 255, .9); box-shadow: 0 1px 2px rgba(20,24,28,.06), 0 14px 40px -14px rgba(60, 50, 90, .35); white-space: nowrap; }
.logo { display: flex; align-items: center; gap: 9px; font-family: var(--display); font-weight: 600; font-size: 19px; letter-spacing: -.03em; margin-right: 14px; }
.logo svg { width: 24px; height: 24px; }
.pill .links { display: flex; gap: 4px; margin-right: 8px; }
.pill .links a { padding: 8px 13px; border-radius: 999px; color: var(--soft); font-size: 14.5px; transition: background .15s ease, color .15s ease; }
.pill .links a:hover, .pill .links a.on { background: rgba(20, 24, 28, .06); color: var(--text); }
.who { display: flex; align-items: center; gap: 8px; padding: 0 8px 0 4px; color: var(--soft); font-size: 14px; }
.who img { width: 28px; height: 28px; border-radius: 50%; }

/* buttons and fields */
.btn { display: inline-flex; align-items: center; justify-content: center; gap: 9px; border: 0; border-radius: 999px; padding: 11px 20px; font-weight: 600; font-size: 15px; cursor: pointer; background: var(--accent); color: var(--accent-ink); transition: transform .12s ease, background .15s ease, box-shadow .2s ease; }
.btn:hover { background: var(--accent-bright); box-shadow: 0 10px 26px -10px rgba(67, 97, 27, .7); } .btn:active { transform: translateY(1px); } .btn:disabled { opacity: .4; cursor: default; box-shadow: none; }
.btn.ghost { background: rgba(255,255,255,.7); color: var(--text); border: 1px solid var(--line); } .btn.ghost:hover { background: #fff; box-shadow: var(--shadow); }
.btn.danger { background: transparent; color: var(--bad); border: 1px solid rgba(180, 50, 47, .35); } .btn.danger:hover { background: var(--bad-soft); box-shadow: none; }
.btn.big { padding: 15px 28px; font-size: 16.5px; }
.btn.dark { background: #15181c; color: #fff; } .btn.dark:hover { background: #2a2f36; box-shadow: 0 10px 26px -10px rgba(20,24,28,.6); }
.btn .arrow { transition: transform .2s ease; } .btn:hover .arrow { transform: translateX(4px); }
.field { width: 100%; background: #fff; border: 1px solid var(--line); border-radius: 14px; padding: 14px 16px; outline: none; font-size: 15.5px; transition: border-color .15s ease, box-shadow .15s ease; }
.field:focus { border-color: var(--accent-bright); box-shadow: 0 0 0 4px var(--accent-soft); }

/* hero */
.hero { position: relative; height: 100vh; min-height: 720px; max-height: 1120px; overflow: hidden; isolation: isolate; }
.hero .scene { position: absolute; inset: 0; z-index: -2; } .hero .scene svg { width: 100%; height: 100%; display: block; }
.hero .copy { position: absolute; left: 0; right: 0; top: 23%; text-align: center; padding: 0 24px; animation: rise 1.1s cubic-bezier(.2, .8, .2, 1) both; }
@keyframes rise { from { opacity: 0; transform: translateY(22px); } }
.hero h1 { font-size: clamp(40px, 5.9vw, 86px); line-height: 1.04; letter-spacing: -.04em; font-weight: 500; color: #16181b; }
.hero h1 em { font-family: "Instrument Serif", Georgia, serif; font-style: italic; font-weight: 400; color: var(--accent); letter-spacing: -.02em; font-size: 1.08em; }
.hero .lede { margin: 22px auto 0; max-width: 560px; color: #3d444c; font-size: 18.5px; }
.hero .cta { margin-top: 30px; display: flex; gap: 12px; justify-content: center; flex-wrap: wrap; }
.hero .assure { margin-top: 18px; color: #5b626a; font-size: 13.5px; }
.tile-glass { position: absolute; z-index: -1; border-radius: 16px; background: rgba(255, 255, 255, .26); border: 1px solid rgba(255, 255, 255, .62); backdrop-filter: blur(7px) saturate(1.25); -webkit-backdrop-filter: blur(7px) saturate(1.25); box-shadow: 0 8px 30px -12px rgba(50, 40, 90, .35), inset 0 1px 0 rgba(255,255,255,.7); animation: bob 7s ease-in-out infinite alternate; }
@keyframes bob { to { transform: translateY(-14px); } }
.glint { animation: shimmer 7s ease-in-out infinite; } @keyframes shimmer { 0%, 100% { opacity: .15; transform: translateX(-14px); } 50% { opacity: .9; transform: translateX(14px); } }
.bird { animation: fly linear infinite; } @keyframes fly { from { transform: translate(calc(var(--x) - 260px), calc(var(--y) + 60px)) scale(var(--s)); } to { transform: translate(calc(var(--x) + 520px), calc(var(--y) - 150px)) scale(var(--s)); } }
.wing { animation: flap .9s ease-in-out infinite alternate; transform-origin: center; } @keyframes flap { to { transform: scaleY(.25); } }
.fade { position: absolute; left: 0; right: 0; bottom: 0; height: 120px; background: linear-gradient(180deg, rgba(251,250,246,0), var(--bg)); z-index: -1; pointer-events: none; }

/* landing sections */
.wrap { max-width: 1160px; margin: 0 auto; padding: 0 32px; }
.section { padding: 120px 0; }
.kicker { display: inline-block; font-family: var(--mono); font-size: 12px; letter-spacing: .14em; text-transform: uppercase; color: var(--accent); margin-bottom: 16px; }
.section h2 { font-size: clamp(32px, 4vw, 54px); line-height: 1.06; max-width: 780px; } .section h2 em { font-family: "Instrument Serif", Georgia, serif; font-style: italic; font-weight: 400; color: var(--accent); }
.section .sub { margin-top: 18px; color: var(--soft); font-size: 18px; max-width: 620px; }
.reveal { opacity: 0; transform: translateY(34px); transition: opacity .9s ease, transform .9s cubic-bezier(.2, .8, .2, 1); } .reveal.in { opacity: 1; transform: none; }
.split { display: grid; grid-template-columns: 1fr 1.15fr; gap: 64px; align-items: center; }
.ticks { list-style: none; padding: 0; margin: 28px 0 0; display: grid; gap: 14px; } .ticks li { display: flex; gap: 12px; align-items: flex-start; color: var(--soft); }
.ico { width: 18px; height: 18px; color: var(--accent); flex: none; margin-top: 4px; }
.console { border-radius: 22px; background: #14171c; color: #cfd6df; box-shadow: 0 40px 90px -30px rgba(30, 30, 60, .55), 0 0 0 1px rgba(20,24,28,.9); overflow: hidden; font-family: var(--mono); }
.console .bar { display: flex; align-items: center; gap: 7px; padding: 14px 18px; border-bottom: 1px solid rgba(255,255,255,.07); } .console .bar i { width: 11px; height: 11px; border-radius: 50%; background: #323a46; } .console .bar span { margin-left: auto; font-size: 11px; color: #7d8898; letter-spacing: .08em; }
.console .lines { padding: 22px 22px 26px; min-height: 330px; font-size: 13px; line-height: 1.55; }
.cl { display: flex; gap: 12px; align-items: baseline; padding: 5px 0; } .cl .text { min-width: 0; word-break: break-word; }
.cl.cmd { color: #fff; margin-bottom: 8px; } .cl .prompt { color: #9fd66b; }
.cl .tag { flex: none; width: 84px; font-size: 10.5px; letter-spacing: .08em; padding: 2px 0; text-align: center; border-radius: 6px; background: rgba(159, 214, 107, .14); color: #9fd66b; }
.cl.fail .tag { background: rgba(248, 113, 113, .16); color: #fca5a5; } .cl.wait .tag { background: rgba(251, 191, 36, .16); color: #fcd34d; } .cl.wait .text { color: #fff; }
.caret { width: 8px; height: 15px; background: #9fd66b; align-self: center; animation: blink 1s steps(2) infinite; } .cl.done .caret { display: none; } @keyframes blink { 50% { opacity: 0; } }
.metrics { margin-top: 52px; display: grid; grid-template-columns: repeat(4, 1fr); border-radius: 26px; background: var(--surface); border: 1px solid var(--line-soft); box-shadow: var(--shadow); overflow: hidden; }
.metric { padding: 40px 32px; border-right: 1px solid var(--line-soft); } .metric:last-child { border-right: 0; }
.metric b { display: block; font-family: var(--display); font-weight: 500; font-size: clamp(44px, 5vw, 72px); line-height: 1; letter-spacing: -.045em; } .metric > span { display: block; margin-top: 14px; color: var(--muted); font-size: 14.5px; }
.grid4, .grid3 { display: grid; gap: 18px; margin-top: 52px; } .grid4 { grid-template-columns: repeat(4, 1fr); } .grid3 { grid-template-columns: repeat(3, 1fr); }
.tile { padding: 30px; border-radius: 22px; background: var(--surface); border: 1px solid var(--line-soft); transition: transform .3s ease, box-shadow .3s ease; }
.tile:hover { transform: translateY(-5px); box-shadow: 0 30px 60px -30px rgba(40, 40, 80, .3); }
.tile h3 { font-size: 20px; margin-bottom: 10px; } .tile p { color: var(--soft); font-size: 15px; } .tile .n { font-family: var(--mono); color: var(--accent); font-size: 13px; margin-bottom: 22px; } .tile > .ico { width: 24px; height: 24px; margin: 0 0 18px; }
.band { background: #f1efe7; }
.final { text-align: center; padding: 90px 32px; border-radius: 32px; background: linear-gradient(180deg, #eef3e2, #f7f4ea); border: 1px solid #dfe7cc; }
.final h2 { margin: 0 auto; } .final p { margin: 18px auto 0; color: var(--soft); font-size: 18px; max-width: 520px; } .final .cta { margin-top: 32px; display: flex; justify-content: center; }
.foot { padding: 36px 0 60px; color: var(--muted); font-size: 14px; display: flex; justify-content: space-between; flex-wrap: wrap; gap: 12px; }

/* sign-in gate */
.gate-page { min-height: 100vh; display: grid; place-items: center; padding: 120px 24px 60px; background: radial-gradient(900px 500px at 50% 0%, #f3e9e2, transparent 70%), var(--bg); }
.gate-card { width: 100%; max-width: 440px; text-align: center; padding: 44px 36px; border-radius: 28px; background: var(--surface); border: 1px solid var(--line-soft); box-shadow: var(--shadow); }
.gate-card h1 { font-size: 32px; } .gate-card p { color: var(--soft); margin-top: 10px; } .gate-card form { margin-top: 26px; display: grid; gap: 10px; } .gate-card .btn { width: 100%; margin-top: 22px; } .gate-card form .btn { margin-top: 0; }
.gate-card .small { font-size: 13px; color: var(--muted); margin-top: 18px; }

/* app */
.page { max-width: 1080px; margin: 0 auto; padding: 128px 32px 110px; }
.page-head h1 { font-size: 42px; } .page-head p { color: var(--soft); margin-top: 8px; font-size: 17px; max-width: 620px; }
.start { margin-top: 30px; padding: 30px; border-radius: 26px; background: var(--surface); border: 1px solid var(--line-soft); box-shadow: var(--shadow); }
.start h2 { font-size: 22px; } .start .hint { color: var(--soft); margin-top: 6px; font-size: 15px; }
.start form { margin-top: 20px; display: grid; grid-template-columns: 1fr auto; gap: 12px; align-items: start; } .start .inputs { display: grid; gap: 10px; }
.or { display: flex; align-items: center; gap: 12px; color: var(--muted); font-size: 12px; text-transform: uppercase; letter-spacing: .12em; } .or::before, .or::after { content: ""; height: 1px; flex: 1; background: var(--line); }
.flow { margin-top: 24px; padding-top: 22px; border-top: 1px solid var(--line-soft); display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; }
.flow div { display: flex; gap: 12px; align-items: flex-start; color: var(--soft); font-size: 14px; line-height: 1.5; } .flow b { flex: none; width: 26px; height: 26px; border-radius: 50%; display: grid; place-items: center; background: var(--accent-soft); color: var(--accent); font-family: var(--mono); font-size: 12px; font-weight: 600; } .flow strong { color: var(--text); display: block; font-weight: 600; }
.list-head { margin: 52px 0 14px; display: flex; align-items: baseline; justify-content: space-between; } .list-head h2 { font-size: 22px; } .list-head span { color: var(--muted); font-size: 14px; }
.rows { border-radius: 22px; background: var(--surface); border: 1px solid var(--line-soft); overflow: hidden; }
.row { display: grid; grid-template-columns: minmax(0, 1.2fr) minmax(0, 1.6fr) auto; gap: 20px; align-items: center; padding: 18px 22px; border-bottom: 1px solid var(--line-soft); transition: background .15s ease; } .row:last-child { border-bottom: 0; } .row:hover { background: #faf9f5; }
.row .name { font-family: var(--mono); font-size: 14px; font-weight: 500; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; } .row .when { color: var(--muted); font-size: 12.5px; margin-top: 3px; }
.row .line { color: var(--soft); font-size: 14.5px; } .row .go { color: var(--muted); font-size: 18px; }
