.chip { display: inline-flex; align-items: center; gap: 6px; padding: 3px 11px; border-radius: 999px; font-size: 12.5px; font-weight: 600; white-space: nowrap; background: var(--raised); color: var(--soft); }
.chip.ok { background: var(--accent-soft); color: var(--accent); } .chip.bad { background: var(--bad-soft); color: var(--bad); } .chip.warn { background: var(--warn-soft); color: var(--warn); }
.dot { width: 7px; height: 7px; border-radius: 50%; background: currentColor; } .pulse { animation: pulse 1.2s ease-in-out infinite; } @keyframes pulse { 50% { opacity: .25; } }
.crumb { color: var(--muted); font-size: 14px; display: inline-block; margin-bottom: 14px; } .crumb:hover { color: var(--text); }
.title { display: flex; align-items: center; gap: 14px; flex-wrap: wrap; } .title h1 { font-size: 34px; word-break: break-all; }
.subtitle { color: var(--muted); font-size: 13.5px; margin-top: 8px; word-break: break-all; }
.verdict { margin-top: 24px; padding: 22px 26px; border-radius: 22px; background: var(--surface); border: 1px solid var(--line-soft); box-shadow: var(--shadow); font-family: var(--display); font-size: 22px; letter-spacing: -.02em; display: flex; gap: 14px; align-items: center; }
.verdict::before { content: ""; width: 12px; height: 12px; border-radius: 50%; background: var(--muted); flex: none; } .verdict.ok::before { background: var(--accent-bright); box-shadow: 0 0 0 5px var(--accent-soft); } .verdict.warn::before { background: #d19a1c; box-shadow: 0 0 0 5px var(--warn-soft); }
.stats { display: grid; grid-template-columns: repeat(5, 1fr); gap: 12px; margin-top: 14px; }
.stat { padding: 18px 20px; border-radius: 18px; background: var(--surface); border: 1px solid var(--line-soft); } .stat b { display: block; font-family: var(--display); font-weight: 500; font-size: 30px; letter-spacing: -.03em; line-height: 1.1; } .stat span { color: var(--muted); font-size: 13px; }
