@media (max-width: 980px) { .split { grid-template-columns: 1fr; } .grid4, .metrics { grid-template-columns: repeat(2, 1fr); } .grid3, .flow { grid-template-columns: 1fr; } .metric:nth-child(2) { border-right: 0; } .metric:nth-child(-n+2) { border-bottom: 1px solid var(--line-soft); } .stats { grid-template-columns: repeat(2, 1fr); } .phases { grid-template-columns: repeat(2, 1fr); } .section { padding: 80px 0; } .pill .links { display: none; } .start form, .row { grid-template-columns: 1fr; } .tile-glass { display: none; } }
@media (prefers-reduced-motion: reduce) { .reveal { opacity: 1; transform: none; transition: none; } .tile-glass, .glint, .bird, .wing, .hero .copy { animation: none; } }

