"""Fish Audio (free S2.1 Pro) speech in a cloned voice, from a short reference recording.
usage: fish_clone.py <reference.wav> <reference transcript> <text or .txt> <out.mp3|.wav>"""
import os, struct, sys, urllib.error, urllib.request

KEY = os.path.expanduser('~/.config/fish-audio/key')


def pack(o):
    """minimal msgpack encoder (dict, list, str, bytes, int, float, bool, None)"""
    if o is None: return b'\xc0'
    if o is True: return b'\xc3'
    if o is False: return b'\xc2'
    if isinstance(o, int): return b'\xd3' + struct.pack('>q', o)
    if isinstance(o, float): return b'\xcb' + struct.pack('>d', o)
    if isinstance(o, str):
        b = o.encode(); return b'\xdb' + struct.pack('>I', len(b)) + b
    if isinstance(o, bytes): return b'\xc6' + struct.pack('>I', len(o)) + o
    if isinstance(o, (list, tuple)): return b'\xdd' + struct.pack('>I', len(o)) + b''.join(pack(x) for x in o)
    if isinstance(o, dict): return b'\xdf' + struct.pack('>I', len(o)) + b''.join(pack(k) + pack(v) for k, v in o.items())
    raise TypeError(type(o))


def clone(ref, ref_text, text, out, speed=1.0):
    body = {'text': text, 'format': out.rsplit('.', 1)[-1], 'references': [{'audio': open(ref, 'rb').read(), 'text': ref_text}], 'prosody': {'speed': speed, 'volume': 0}}
    req = urllib.request.Request('https://api.fish.audio/v1/tts', data=pack(body), headers={'Authorization': 'Bearer ' + open(KEY).read().strip(), 'Content-Type': 'application/msgpack', 'model': 's2.1-pro-free'})
    try:
        audio = urllib.request.urlopen(req, timeout=300).read()
    except urllib.error.HTTPError as e:
        sys.exit(f'Fish Audio error {e.code}: {e.read().decode()[:400]}')
    open(out, 'wb').write(audio)
    return len(audio)


if __name__ == '__main__':
    r, rt, t, o = sys.argv[1:5]
    print(o, clone(r, rt, open(t).read() if t.endswith('.txt') else t, o) // 1024, 'KB')

