"""Fish Audio text-to-speech (free S2.1 Pro tier).
usage: fish_tts.py <text or .txt file> <out.mp3|.wav> [voice_id]      |      fish_tts.py --check"""
import json, os, sys, urllib.error, urllib.request

KEYS = [os.path.expanduser('~/.config/fish-audio/key'), os.path.expanduser('~/Documents/BUGGER/FISH_KEY.txt')]
MODEL = 's2.1-pro-free'


def key():
    for p in KEYS:
        if os.path.exists(p):
            k = open(p).read().strip()
            if k and 'PASTE' not in k:
                return k
    sys.exit('no Fish Audio key found: paste it into ~/Documents/BUGGER/FISH_KEY.txt')


def call(url, body=None, headers=None):
    h = {'Authorization': 'Bearer ' + key(), **(headers or {})}
    req = urllib.request.Request(url, data=json.dumps(body).encode() if body is not None else None, headers=h)
    try:
        return urllib.request.urlopen(req, timeout=180).read()
    except urllib.error.HTTPError as e:
        sys.exit(f'Fish Audio error {e.code}: {e.read().decode()[:400]}')


def tts(text, out, voice=None):
    body = {'text': text, 'format': out.rsplit('.', 1)[-1]}
    if voice:
        body['reference_id'] = voice
    audio = call('https://api.fish.audio/v1/tts', body, {'Content-Type': 'application/json', 'model': MODEL})
    open(out, 'wb').write(audio)
    print(f'{out}: {len(audio) / 1024:.0f} KB')


if __name__ == '__main__':
    if sys.argv[1] == '--check':
        tts('This is a test of the Fish Audio voice.', '/tmp/fish_check.mp3')
    else:
        t = sys.argv[1]

